-- Phase 1 — Designer 시드 (150 rows from designers.json)
-- 원본: docs/00-mock/designers.json (또는 Downloads/designers.json)
--
-- 주의:
--   * user_id는 NULL로 시드 — Auth 연결 PDCA 시점에 UPDATE로 연결
--   * _specialties의 'Extensions'는 keyword 마스터 'Hair Extensions'로 정규화 (Python 전처리)
--   * _temp_specialties / _temp_hair_type_experience는 designer_keyword 시드 후 DROP
--   * salon_id는 external_ref JOIN으로 매핑. 존재하지 않는 _salon_ref는 NULL 처리

BEGIN;

INSERT INTO public.designer_profile
